-- Native typed payroll/source adoption. Frozen legacy payroll stays untouched.
CREATE TABLE ty_pay_catalog_policy(version text PRIMARY KEY,policy jsonb NOT NULL);
INSERT INTO ty_pay_catalog_policy VALUES('tyhr-pay-catalog-v1','{"version":"tyhr-pay-catalog-v1","source":"docs/design/pay-items.json","applicability":"Applicable statutory and effective contractual obligations cannot be disabled by an optional item toggle; missing facts remain pending","value_states":["confirmed_zero","not_applicable","pending_review","missing_required"],"source_identity":"authoritative fact/economic obligation plus purpose; aliases and revisions do not mint another payable","ledger_policy":"gross wage/reimbursement/personal deductions/withholding/employer costs/noncash/base/agency/restricted funds/procurement remain separate","cost_policy":"one economic cost atom plus recognition basis; included detail and noncash rental value create no additional cost","scope_policy":"tax/social/MPF/ADW/minimum/ordinary-wage inclusion resolved independently by item nature/effective jurisdiction and evidence","execution_policy":"typed dependency DAG, exact intermediate values, immutable versions, isolated extensions; AI drafts cannot execute or publish"}'::jsonb);
CREATE TABLE ty_pay_item_catalog(
 code text PRIMARY KEY,name text NOT NULL,system text NOT NULL CHECK(system IN('COMMON','CN_PAYROLL','HK_PAYROLL')),
 category text NOT NULL,unit text NOT NULL,output_ledger text NOT NULL,metadata jsonb NOT NULL,policy_version text NOT NULL DEFAULT 'tyhr-pay-catalog-v1' REFERENCES ty_pay_catalog_policy(version)
);
INSERT INTO ty_pay_item_catalog(code,name,system,category,unit,output_ledger,metadata)VALUES
