INSERT INTO sys_perm_resource(resource_code,label)VALUES('payroll_config','薪酬体系及项目设置'),('payroll_sources','薪酬来源采用'),('payroll_confirm','薪酬复核确认'),('payroll_cost','人力成本'),('payroll_self','本人工资单')ON CONFLICT DO NOTHING;
-- Existing payroll_run and payroll_slips_read_all remain actual functional resources.
CREATE TABLE ty_pay_config(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint NOT NULL,
 employment_id bigint,person_id bigint,kind text NOT NULL CHECK(kind IN('systems','relationship','profile','rulebook','wage_calendar','formula_proposal')),
 stable_key text NOT NULL,revision integer NOT NULL CHECK(revision>0),status text NOT NULL DEFAULT 'draft'CHECK(status IN('draft','approved','superseded','rejected')),
 system text CHECK(system IN('CN_PAYROLL','HK_PAYROLL')),currency text CHECK(currency IN('CNY','HKD')),
 valid_from date NOT NULL,valid_to date,data jsonb NOT NULL,evidence_ref text NOT NULL CHECK(length(btrim(evidence_ref))>=4),
 created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),approved_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 FOREIGN KEY(company_id,group_id)REFERENCES ty_company(id,group_id),FOREIGN KEY(employment_id,company_id,group_id)REFERENCES ty_employment(id,company_id,group_id),FOREIGN KEY(person_id,group_id)REFERENCES ty_person(id,group_id),
 CHECK(valid_to IS NULL OR valid_to>valid_from),CHECK((employment_id IS NULL)=(person_id IS NULL)),CHECK(approved_by IS NULL OR approved_by<>created_by),
 CHECK(status NOT IN('approved','superseded')OR(approved_by IS NOT NULL AND approved_at IS NOT NULL)),UNIQUE(group_id,company_id,kind,stable_key,revision)
);
CREATE TABLE ty_pay_batch(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL,company_id bigint NOT NULL,
 system text NOT NULL CHECK(system IN('CN_PAYROLL','HK_PAYROLL')),currency text NOT NULL CHECK(currency IN('CNY','HKD')),period date NOT NULL CHECK(extract(day FROM period)=1),
 kind text NOT NULL CHECK(kind IN('regular','supplement','correction','cost_only')),label text NOT NULL,relationship_config_id bigint NOT NULL REFERENCES ty_pay_config(id),pay_subject_key text NOT NULL,tax_subject_key text NOT NULL,contribution_subject_key text NOT NULL,rulebook_id bigint NOT NULL REFERENCES ty_pay_config(id),
 status text NOT NULL DEFAULT 'draft'CHECK(status IN('draft','calculated','reviewed','confirmed','cancelled')),revision integer NOT NULL DEFAULT 1,
 created_by bigint NOT NULL REFERENCES sys_account(id),confirmed_by bigint REFERENCES sys_account(id),execution_actor_id bigint REFERENCES sys_account(id),workflow_instance_id bigint REFERENCES ty_workflow_instance(id),confirmed_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 FOREIGN KEY(company_id,group_id)REFERENCES ty_company(id,group_id),CHECK(confirmed_by IS NULL OR confirmed_by<>created_by),
 CHECK((status='confirmed')=(confirmed_by IS NOT NULL AND confirmed_at IS NOT NULL)),CHECK((system='CN_PAYROLL')=(currency='CNY'))
);
CREATE TABLE ty_pay_preview(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,batch_id bigint NOT NULL REFERENCES ty_pay_batch(id),baseline_revision integer NOT NULL,
 source_hash text NOT NULL,request jsonb NOT NULL,planned jsonb NOT NULL,status text NOT NULL DEFAULT 'draft'CHECK(status IN('draft','reviewed','adopted','cancelled')),
 created_by bigint NOT NULL REFERENCES sys_account(id),reviewed_by bigint REFERENCES sys_account(id),review_ref text,workflow_instance_id bigint REFERENCES ty_workflow_instance(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 CHECK(reviewed_by IS NULL OR reviewed_by<>created_by),CHECK(status NOT IN('reviewed','adopted')OR(reviewed_by IS NOT NULL AND length(btrim(review_ref))>=4))
);
CREATE TABLE ty_pay_row(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,batch_id bigint NOT NULL REFERENCES ty_pay_batch(id),group_id bigint NOT NULL,company_id bigint NOT NULL,
 person_id bigint,employment_id bigint,relationship_config_id bigint REFERENCES ty_pay_config(id),row_key text NOT NULL,totals jsonb NOT NULL DEFAULT '{}'::jsonb,
 FOREIGN KEY(company_id,group_id)REFERENCES ty_company(id,group_id),FOREIGN KEY(person_id,group_id)REFERENCES ty_person(id,group_id),FOREIGN KEY(employment_id,company_id,group_id)REFERENCES ty_employment(id,company_id,group_id),
 CHECK((person_id IS NULL)=(employment_id IS NULL)),UNIQUE(batch_id,row_key)
);
CREATE TABLE ty_pay_obligation(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL,company_id bigint NOT NULL,person_id bigint,employment_id bigint,
 economic_key text NOT NULL,purpose text NOT NULL CHECK(purpose IN('employee_cash','reimbursement','personal_deduction','employee_withholding','employer_cost','noncash_shadow','statistical_base','agency_funds','restricted_payment_funds','procurement_service')),
 currency text NOT NULL CHECK(currency IN('CNY','HKD')),unit text NOT NULL DEFAULT 'currency_amount',created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 FOREIGN KEY(company_id,group_id)REFERENCES ty_company(id,group_id),FOREIGN KEY(person_id,group_id)REFERENCES ty_person(id,group_id),FOREIGN KEY(employment_id,company_id,group_id)REFERENCES ty_employment(id,company_id,group_id),
 CHECK((person_id IS NULL)=(employment_id IS NULL)),UNIQUE(group_id,economic_key,purpose)
);
CREATE TABLE ty_pay_adoption(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,obligation_id bigint NOT NULL REFERENCES ty_pay_obligation(id),batch_id bigint NOT NULL REFERENCES ty_pay_batch(id),preview_id bigint NOT NULL REFERENCES ty_pay_preview(id),
 source_domain text NOT NULL,source_id text NOT NULL,source_revision text NOT NULL,source_hash text NOT NULL,source_snapshot jsonb NOT NULL,
 target numeric(24,2)NOT NULL,prior_confirmed numeric(24,2)NOT NULL,delta numeric(24,2)NOT NULL,
 state text NOT NULL DEFAULT 'reserved'CHECK(state IN('reserved','confirmed','released')),created_by bigint NOT NULL REFERENCES sys_account(id),reviewed_by bigint NOT NULL REFERENCES sys_account(id),execution_actor_id bigint NOT NULL REFERENCES sys_account(id),
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(target>=0),CHECK(delta=target-prior_confirmed),CHECK(created_by<>reviewed_by),UNIQUE(batch_id,obligation_id)
);
CREATE UNIQUE INDEX ty_pay_adoption_active ON ty_pay_adoption(obligation_id)WHERE state='reserved';
CREATE TABLE ty_pay_item(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,row_id bigint NOT NULL REFERENCES ty_pay_row(id),adoption_id bigint NOT NULL UNIQUE REFERENCES ty_pay_adoption(id),code text NOT NULL REFERENCES ty_pay_item_catalog(code),
 category text NOT NULL,output_ledger text NOT NULL,unit text NOT NULL,cash_wage_effect text NOT NULL,cost_direction integer NOT NULL CHECK(cost_direction IN(-1,1)),amount numeric(24,2)NOT NULL,exact_numerator text NOT NULL,exact_denominator text NOT NULL,
 wage_tags jsonb NOT NULL,source_key text NOT NULL,cost_atom text,cost_membership text NOT NULL CHECK(cost_membership IN('independent','included_in_parent','excluded','pending_review')),
 CHECK(exact_numerator ~ '^-?[0-9]+$'AND exact_denominator ~ '^[1-9][0-9]*$')
);
CREATE TABLE ty_pay_cost_entry(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,adoption_id bigint NOT NULL UNIQUE REFERENCES ty_pay_adoption(id),group_id bigint NOT NULL,company_id bigint NOT NULL,batch_id bigint NOT NULL REFERENCES ty_pay_batch(id),
 period date NOT NULL,currency text NOT NULL CHECK(currency IN('CNY','HKD')),economic_component text NOT NULL,recognition_basis text NOT NULL,
 amount numeric(24,2)NOT NULL,inclusion_key text NOT NULL,source_ref text NOT NULL,
 FOREIGN KEY(company_id,group_id)REFERENCES ty_company(id,group_id)
);
CREATE TABLE ty_pay_wage_day(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,batch_id bigint NOT NULL REFERENCES ty_pay_batch(id),row_id bigint NOT NULL REFERENCES ty_pay_row(id),employment_id bigint NOT NULL REFERENCES ty_employment(id),
 root_key text NOT NULL,version integer NOT NULL,work_date date NOT NULL,eligible_wages numeric(24,4)NOT NULL CHECK(eligible_wages>=0),excluded_wages numeric(24,4)NOT NULL CHECK(excluded_wages>=0),
 excluded_days numeric(10,4)NOT NULL CHECK(excluded_days BETWEEN 0 AND 1),ordinary_wages numeric(24,4)NOT NULL CHECK(ordinary_wages>=0),mapping_config_id bigint NOT NULL REFERENCES ty_pay_config(id),
 source_hash text NOT NULL,CHECK(excluded_wages<=eligible_wages),UNIQUE(root_key,version,work_date)
);
CREATE TABLE ty_pay_payslip(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,row_id bigint NOT NULL UNIQUE REFERENCES ty_pay_row(id),published_by bigint NOT NULL REFERENCES sys_account(id),published_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 publication_ref text NOT NULL CHECK(length(btrim(publication_ref))>=4),status text NOT NULL DEFAULT 'published'CHECK(status IN('published','withdrawn'))
);
-- No raw salary is cached in generic command receipts: only entity IDs/metadata.
CREATE TABLE ty_pay_command(actor_id bigint NOT NULL,operation text NOT NULL,operation_key text NOT NULL,input_hash text NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(actor_id,operation,operation_key));
CREATE FUNCTION fn_ty_pay_immutable()RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$BEGIN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='薪酬已确认事实和不可变血缘不得改写';END;$$;
CREATE TRIGGER ty_pay_catalog_immutable BEFORE UPDATE OR DELETE ON ty_pay_item_catalog FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_immutable();
CREATE TRIGGER ty_pay_item_immutable BEFORE UPDATE OR DELETE ON ty_pay_item FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_immutable();
CREATE TRIGGER ty_pay_cost_immutable BEFORE UPDATE OR DELETE ON ty_pay_cost_entry FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_immutable();
CREATE TRIGGER ty_pay_wage_day_immutable BEFORE UPDATE OR DELETE ON ty_pay_wage_day FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_immutable();
CREATE TRIGGER ty_pay_command_immutable BEFORE UPDATE OR DELETE ON ty_pay_command FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_immutable();
CREATE FUNCTION fn_ty_pay_identity_guard()RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
DECLARE e public.ty_employment%ROWTYPE;b public.ty_pay_batch%ROWTYPE;r public.ty_pay_row%ROWTYPE;c public.ty_pay_config%ROWTYPE;oldj jsonb;newj jsonb:=to_jsonb(NEW);
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='薪酬身份/审批历史不可删除';END IF;
 IF newj->>'employment_id' IS NOT NULL THEN SELECT * INTO e FROM public.ty_employment WHERE id=(newj->>'employment_id')::bigint;IF NOT FOUND OR e.person_id IS DISTINCT FROM (newj->>'person_id')::bigint OR e.group_id IS DISTINCT FROM(newj->>'group_id')::bigint OR e.company_id IS DISTINCT FROM(newj->>'company_id')::bigint THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='薪酬真实雇佣、人员、公司、集团不一致';END IF;END IF;
 IF TG_OP='UPDATE' THEN
  oldj:=to_jsonb(OLD);
  IF oldj-'status'-'approved_by'-'approved_at'-'totals'-'revision'-'confirmed_by'-'confirmed_at'-'execution_actor_id'-'workflow_instance_id' IS DISTINCT FROM newj-'status'-'approved_by'-'approved_at'-'totals'-'revision'-'confirmed_by'-'confirmed_at'-'execution_actor_id'-'workflow_instance_id' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='薪酬稳定身份及发布内容不可改写';END IF;
  IF TG_TABLE_NAME='ty_pay_config'AND oldj->>'status' IN('approved','superseded')AND(newj->>'status' NOT IN('approved','superseded')OR newj->>'approved_by' IS DISTINCT FROM oldj->>'approved_by' OR newj->>'approved_at' IS DISTINCT FROM oldj->>'approved_at')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已发布配置只可创建新修订';END IF;
  IF TG_TABLE_NAME='ty_pay_batch'AND oldj->>'status'='confirmed'AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='封存工资不可重算覆盖，请建立更正批次';END IF;
 END IF;
 IF TG_TABLE_NAME='ty_pay_row' THEN SELECT * INTO b FROM public.ty_pay_batch WHERE id=NEW.batch_id;IF b.group_id<>NEW.group_id OR b.company_id<>NEW.company_id OR b.status='confirmed' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='工资行与批次范围或状态不符';END IF;END IF;
 IF TG_TABLE_NAME='ty_pay_batch' THEN SELECT * INTO c FROM public.ty_pay_config WHERE id=NEW.rulebook_id;IF c.kind<>'rulebook'OR c.group_id<>NEW.group_id OR c.company_id<>NEW.company_id OR c.system<>NEW.system OR c.currency<>NEW.currency OR c.status<>'approved' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='批次须引用范围体系币种一致的已批准规则';END IF;END IF;
 RETURN NEW;
END;$$;
CREATE TRIGGER ty_pay_config_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_pay_config FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_identity_guard();
CREATE TRIGGER ty_pay_batch_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_pay_batch FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_identity_guard();
CREATE TRIGGER ty_pay_row_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_pay_row FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_identity_guard();
CREATE TRIGGER ty_pay_obligation_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_pay_obligation FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_identity_guard();
CREATE FUNCTION fn_ty_pay_adoption_guard()RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
DECLARE o public.ty_pay_obligation%ROWTYPE;b public.ty_pay_batch%ROWTYPE;p public.ty_pay_preview%ROWTYPE;prior numeric;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='采用须显式释放而非删除';END IF;
 SELECT * INTO o FROM public.ty_pay_obligation WHERE id=NEW.obligation_id FOR UPDATE;SELECT * INTO b FROM public.ty_pay_batch WHERE id=NEW.batch_id;SELECT * INTO p FROM public.ty_pay_preview WHERE id=NEW.preview_id;
 IF b.status='confirmed'OR o.group_id<>b.group_id OR o.company_id<>b.company_id OR o.currency<>b.currency OR p.batch_id<>b.id OR p.status NOT IN('reviewed','adopted')OR NEW.reviewed_by<>p.reviewed_by THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='采用主体币种/预演复核/封存状态不一致';END IF;
 IF TG_OP='UPDATE' THEN
  IF OLD.state<>'reserved'OR NEW.state NOT IN('confirmed','released')OR to_jsonb(OLD)-'state' IS DISTINCT FROM to_jsonb(NEW)-'state' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='采用只能从占用确认或释放，金额与来源不可改写';END IF;
 ELSE
  SELECT coalesce(sum(delta),0)INTO prior FROM public.ty_pay_adoption WHERE obligation_id=o.id AND state='confirmed';
  IF prior<>NEW.prior_confirmed THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='累计已确认采用已变化，请重新预演';END IF;
 END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_pay_adoption_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_pay_adoption FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_adoption_guard();
CREATE FUNCTION fn_ty_pay_confirm_guard()RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
DECLARE n integer;bad integer;
BEGIN
 IF NEW.status='confirmed'AND OLD.status<>'confirmed' THEN
  SELECT count(*)INTO n FROM public.ty_pay_adoption WHERE batch_id=NEW.id AND state='confirmed';
  SELECT count(*)INTO bad FROM public.ty_pay_adoption a LEFT JOIN public.ty_pay_item i ON i.adoption_id=a.id LEFT JOIN public.ty_pay_row r ON r.id=i.row_id WHERE a.batch_id=NEW.id AND(a.state<>'confirmed'OR i.id IS NULL OR r.batch_id<>NEW.id OR i.amount<>a.delta);
  IF n=0 OR bad<>0 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='工资确认须有完整且守恒的原生工资项目/采用账';END IF;
 END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_pay_confirm_guard BEFORE UPDATE ON ty_pay_batch FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_confirm_guard();

CREATE FUNCTION fn_ty_pay_preview_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$BEGIN
 IF TG_OP='DELETE'OR to_jsonb(NEW)-'status'-'reviewed_by'-'review_ref'-'workflow_instance_id' IS DISTINCT FROM to_jsonb(OLD)-'status'-'reviewed_by'-'review_ref'-'workflow_instance_id' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='预演来源快照不可覆盖，只能创建新预演';END IF;
 IF OLD.status IN('adopted','cancelled')AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已采用预演不可改写';END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_pay_preview_guard BEFORE UPDATE OR DELETE ON ty_pay_preview FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_preview_guard();
CREATE FUNCTION fn_ty_pay_item_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE a public.ty_pay_adoption%ROWTYPE;o public.ty_pay_obligation%ROWTYPE;r public.ty_pay_row%ROWTYPE;c public.ty_pay_item_catalog%ROWTYPE;BEGIN
 SELECT * INTO a FROM public.ty_pay_adoption WHERE id=NEW.adoption_id;SELECT * INTO o FROM public.ty_pay_obligation WHERE id=a.obligation_id;SELECT * INTO r FROM public.ty_pay_row WHERE id=NEW.row_id;SELECT * INTO c FROM public.ty_pay_item_catalog WHERE code=NEW.code;
 IF a.state<>'reserved'OR r.batch_id<>a.batch_id OR r.company_id<>o.company_id OR r.person_id IS DISTINCT FROM o.person_id OR r.employment_id IS DISTINCT FROM o.employment_id OR NEW.amount<>a.delta OR NEW.category<>c.category OR NEW.cash_wage_effect IS DISTINCT FROM c.metadata->>'employee_cash_wage_effect' OR NEW.cost_direction<>(CASE WHEN c.metadata->>'employee_cash_wage_effect'='decrease_gross'THEN -1 ELSE 1 END) OR NEW.unit<>c.unit OR NEW.unit<>o.unit OR NEW.output_ledger<>c.output_ledger OR NEW.source_key<>o.economic_key THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='实际工资项目须与同一父义务、人员、批次、净差和目录性质一致';END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_pay_item_guard BEFORE INSERT ON ty_pay_item FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_item_guard();
-- Independent authority checks reuse the existing bounded rational AST evaluator.
-- Stored display totals or caller-provided 'verified' labels cannot confirm pay.
-- Extension authority is closed until a later installed migration supplies it.
CREATE FUNCTION fn_ty_pay_extension_expected(bigint,bigint)RETURNS numeric LANGUAGE plpgsql SET search_path=''AS $$BEGIN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='原生薪税来源适配尚未安装';END;$$;
CREATE FUNCTION fn_ty_pay_extension_key(bigint,bigint)RETURNS text LANGUAGE plpgsql SET search_path=''AS $$BEGIN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='原生薪税来源适配尚未安装';END;$$;
CREATE FUNCTION fn_ty_pay_authority_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE a public.ty_pay_adoption%ROWTYPE;i public.ty_pay_item%ROWTYPE;r public.ty_pay_row%ROWTYPE;p public.ty_pay_config%ROWTYPE;
 book public.ty_pay_config%ROWTYPE;v jsonb;ctx jsonb;entry record;rule jsonb;result jsonb;expected numeric;metric text;number_value numeric;unknowns integer;rid bigint;state text;source_revision integer;source_currency text;sc public.ty_ps_candidate%ROWTYPE;charge public.ty_dorm_charge%ROWTYPE;other_net numeric;
BEGIN
 IF NEW.status<>'confirmed'OR OLD.status='confirmed'THEN RETURN NEW;END IF;
 SELECT * INTO book FROM public.ty_pay_config WHERE id=NEW.rulebook_id;
 FOR a IN SELECT * FROM public.ty_pay_adoption WHERE batch_id=NEW.id LOOP
  SELECT * INTO i FROM public.ty_pay_item WHERE adoption_id=a.id;SELECT * INTO r FROM public.ty_pay_row WHERE id=i.row_id;expected:=NULL;
  IF a.source_domain='payroll_calculation'THEN
   SELECT * INTO p FROM public.ty_pay_config WHERE id=(a.source_snapshot->>'profile_id')::bigint;
   IF p.status<>'approved'OR p.kind<>'profile'OR p.employment_id<>r.employment_id OR p.system<>NEW.system OR p.currency<>NEW.currency OR p.valid_from>NEW.period OR(p.valid_to IS NOT NULL AND p.valid_to<NEW.period+interval '1 month')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='工资参数没有当前可用的已核真实来源';END IF;
   ctx:='{}'::jsonb;
   FOR entry IN SELECT * FROM jsonb_each(book.data->'inputs')LOOP
    IF entry.value->>'source'='profile'THEN
     v:=p.data->'parameters'->coalesce(entry.value->>'key',entry.key);
     IF v IS NULL OR v->>'unit' IS DISTINCT FROM entry.value->>'unit'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='原生工资参数单位不符或缺失';END IF;
     ctx:=ctx||jsonb_build_object(entry.key,v->'value');
    ELSIF entry.value->>'source'='time_report'THEN
     rid:=(a.source_snapshot->>'report_id')::bigint;metric:=coalesce(entry.value->>'metric',entry.key);
     IF metric NOT IN('planned_minutes','actual_minutes','worked_minutes','overtime_minutes','paid_leave_minutes','unpaid_leave_minutes','late_minutes','early_minutes','missing_punches','worked_hours','overtime_hours')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='数据库尚未支持此核勤派生类型，不得只信任调用端金额';END IF;
     EXECUTE 'SELECT v.status FROM public.ty_time_report_version v JOIN public.ty_time_report_root h ON h.current_report_id=v.id WHERE v.id=$1 AND v.group_id=$2 AND v.period=$3 AND(v.company_id IS NULL OR v.company_id=$4)AND h.employment_id=$5 AND h.owner_company_id=$4 AND h.perspective=''employer'''INTO state USING rid,NEW.group_id,NEW.period,NEW.company_id,r.employment_id;
     IF state IS DISTINCT FROM 'confirmed'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='工资只能引用本主体期间已确认核勤';END IF;
     EXECUTE format('SELECT sum(%I),count(*)FILTER(WHERE %I IS NULL)FROM public.ty_time_report_line WHERE report_id=$1 AND employment_id=$2 AND home_company_id=$3 AND NOT receiving_store_only',replace(metric,'_hours','_minutes'),replace(metric,'_hours','_minutes'))INTO number_value,unknowns USING rid,r.employment_id,NEW.company_id;
     IF number_value IS NULL OR unknowns>0 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='核勤输入待核不能充作零';END IF;
     ctx:=ctx||jsonb_build_object(entry.key,CASE WHEN metric LIKE '%_hours'THEN public.fn_ty_payroll_fraction(number_value,60)ELSE to_jsonb(number_value::text)END);
    ELSE RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='工资输入来源适配尚未安装';END IF;
   END LOOP;
   FOR rule IN SELECT * FROM jsonb_array_elements(book.data->'compiled'->'order')LOOP
    result:=public.fn_ty_payroll_eval(rule->'formula',ctx);ctx:=ctx||jsonb_build_object(rule->>'code',result->'v');
    IF rule->>'code'=i.code THEN expected:=public.fn_ty_payroll_money(result->'v');IF i.wage_tags IS DISTINCT FROM rule->'wage_tags'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='工资项目法定工资范围标签不符合已批准规则';END IF;END IF;
   END LOOP;
  ELSIF a.source_domain='leave_cash'THEN
   SELECT round(greatest(gross_numerator::numeric/gross_denominator::numeric-normal_covered,0),2),revision,currency INTO expected,source_revision,source_currency FROM public.ty_leave_lifecycle_cash_obligation WHERE id=a.source_id::bigint AND status='confirmed_source';
   IF source_revision::text IS DISTINCT FROM a.source_revision OR source_currency IS DISTINCT FROM NEW.currency THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='假期现金义务版本或币种已变';END IF;
  ELSIF a.source_domain='performance_result'THEN
   SELECT round(x.amount,2)INTO expected FROM public.ty_perf_result x JOIN public.ty_perf_cycle c ON c.id=x.cycle_id WHERE x.id=a.source_id::bigint AND c.status='confirmed'AND x.result_version=c.result_version AND x.result_version::text=a.source_revision AND x.kind='person_bonus'AND x.company_id=NEW.company_id AND x.person_id=r.person_id AND x.employment_id=r.employment_id AND x.period=NEW.period AND c.currency_code=NEW.currency AND jsonb_array_length(x.issues)=0;
  ELSIF a.source_domain='people_candidate'THEN
   SELECT * INTO sc FROM public.ty_ps_candidate WHERE id=a.source_id::bigint;
   IF sc.group_id<>NEW.group_id OR sc.company_id<>NEW.company_id OR sc.currency<>NEW.currency OR sc.revision::text<>split_part(a.source_revision,':',1) OR EXISTS(SELECT 1 FROM public.ty_ps_candidate x WHERE x.group_id=sc.group_id AND x.module=sc.module AND x.parent_key=sc.parent_key AND x.kind=sc.kind AND x.revision>sc.revision)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='配套候选已被替代或主体币种不符';END IF;
   expected:=sc.target;
   IF sc.kind='company_cost'AND sc.module='dormitory'THEN
    SELECT b.amount-coalesce(sum(c.target),0)INTO expected FROM public.ty_dorm_bill b LEFT JOIN public.ty_dorm_charge c ON c.bill_id=b.id WHERE b.id=(a.source_snapshot->'document'->>'id')::bigint AND b.state='posted'GROUP BY b.id;
   END IF;
   IF sc.kind='employee_charge'THEN
    SELECT * INTO charge FROM public.ty_dorm_charge WHERE id=(a.source_snapshot->>'charge_id')::bigint;
    IF charge.id IS NULL OR NOT charge.payroll_allowed OR charge.disputed OR charge.wage_guard_ref IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='扣结授权或争议状态待核';END IF;
    IF EXISTS(SELECT 1 FROM public.ty_dorm_settlement ds WHERE ds.charge_id=charge.id AND ds.source_key NOT LIKE 'PAY217:%' AND(ds.state IN('unknown','reserved')OR ds.method='payroll'AND ds.state='confirmed'))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='其他渠道结算未知，不能重复收取';END IF;
    SELECT coalesce(sum(CASE WHEN method='refund'THEN -amount ELSE amount END),0)INTO other_net FROM public.ty_dorm_settlement ds WHERE ds.charge_id=charge.id AND ds.source_key NOT LIKE 'PAY217:%' AND ds.state='confirmed';
    expected:=least(greatest(charge.target-other_net,0),charge.payroll_limit);
   END IF;
  ELSIF a.source_domain='statutory_calculation'THEN expected:=public.fn_ty_pay_extension_expected(NEW.id,a.id);
  ELSE RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='未经权威来源适配的金额不能确认';END IF;
  IF expected IS NULL OR a.target<>expected THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='工资采用目标不符合数据库权威来源/已批准公式独立复算';END IF;
 END LOOP;RETURN NEW;
END;$$;
CREATE TRIGGER ty_pay_authority_guard BEFORE UPDATE ON ty_pay_batch FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_authority_guard();

CREATE TABLE ty_pay_source_reference(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,batch_id bigint NOT NULL REFERENCES ty_pay_batch(id),preview_id bigint NOT NULL REFERENCES ty_pay_preview(id),
 source_domain text NOT NULL,source_id text NOT NULL,source_revision text NOT NULL,source_hash text NOT NULL,inclusion_key text NOT NULL,
 reference_amount numeric(24,2)NOT NULL,currency text NOT NULL CHECK(currency IN('CNY','HKD')),source_snapshot jsonb NOT NULL,
 disposition text NOT NULL DEFAULT 'included_parent_no_additional_payable'CHECK(disposition='included_parent_no_additional_payable'),UNIQUE(batch_id,source_domain,source_id)
);
CREATE TRIGGER ty_pay_source_reference_immutable BEFORE UPDATE OR DELETE ON ty_pay_source_reference FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_immutable();

CREATE TRIGGER ty_pay_catalog_policy_immutable BEFORE UPDATE OR DELETE ON ty_pay_catalog_policy FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_immutable();

-- Actual relationship/person keys cannot be renamed to mint the same wage again.
CREATE FUNCTION fn_ty_pay_config_identity()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE prior public.ty_pay_config%ROWTYPE;BEGIN
 IF NEW.kind='relationship'AND NEW.status='approved'AND OLD.status='draft'THEN
  SELECT * INTO prior FROM public.ty_pay_config WHERE kind='relationship'AND employment_id=NEW.employment_id AND status='approved'AND id<>NEW.id ORDER BY revision DESC,id DESC LIMIT 1;
  IF FOUND AND(prior.data->>'actual_relationship_key' IS DISTINCT FROM NEW.data->>'actual_relationship_key'OR prior.data->>'actual_employer_key'IS DISTINCT FROM NEW.data->>'actual_employer_key')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已核实际法律关系及雇主不可换键重置工资';END IF;
  IF EXISTS(SELECT 1 FROM public.ty_pay_config c WHERE c.group_id=NEW.group_id AND c.kind='relationship'AND c.status='approved'AND c.data->>'actual_relationship_key'=NEW.data->>'actual_relationship_key'AND c.person_id<>NEW.person_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='同一实际关系不可改属另一永久人员';END IF;
 END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_pay_config_identity BEFORE UPDATE ON ty_pay_config FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_config_identity();
CREATE FUNCTION fn_ty_pay_employment_identity()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$BEGIN
 IF(NEW.group_id,NEW.company_id,NEW.person_id)IS DISTINCT FROM(OLD.group_id,OLD.company_id,OLD.person_id)AND(EXISTS(SELECT 1 FROM public.ty_pay_config WHERE employment_id=OLD.id)OR EXISTS(SELECT 1 FROM public.ty_pay_row WHERE employment_id=OLD.id))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已有薪酬身份/历史的真实雇佣不可搬人或搬公司';END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_pay_employment_identity BEFORE UPDATE ON ty_employment FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_employment_identity();
INSERT INTO sys_role_resource(role_id,resource_code,can_read,can_write)
SELECT r.id,p.resource_code,true,true FROM sys_role r CROSS JOIN sys_perm_resource p
WHERE r.code IN('ty_group_hr_director','ty_company_hr_director','ty_demo_hr_manager','ty_demo_payroll')AND p.resource_code IN('payroll_config','payroll_sources','payroll_confirm','payroll_cost')ON CONFLICT DO NOTHING;
INSERT INTO sys_role_resource(role_id,resource_code,can_read,can_write)SELECT id,'payroll_config',true,true FROM sys_role WHERE code='ty_demo_config'ON CONFLICT DO NOTHING;
INSERT INTO sys_role_resource(role_id,resource_code,can_read,can_write)SELECT id,'payroll_cost',true,false FROM sys_role WHERE code='boss'ON CONFLICT DO NOTHING;
INSERT INTO sys_role_resource(role_id,resource_code,can_read,can_write)SELECT id,'payroll_self',true,false FROM sys_role WHERE code IN('store_mgr','store_staff','ty_demo_hr_staff','ty_demo_recruiter','ty_demo_trainer','ty_demo_payroll','ty_group_hr_director','ty_company_hr_director')ON CONFLICT DO NOTHING;
-- Reserved namespace must resolve back to the same fee/person/adoption. Legacy
-- payment APIs may not forge a PAY217 key and make another batch mutate its row.
CREATE FUNCTION fn_ty_pay_fee_namespace()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE a public.ty_pay_adoption%ROWTYPE;o public.ty_pay_obligation%ROWTYPE;c public.ty_dorm_charge%ROWTYPE;BEGIN
 IF left(NEW.source_key,7)<>'PAY217:'THEN RETURN NEW;END IF;
 IF NEW.source_key!~'^PAY217:[0-9]{1,18}$'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='保留薪酬结算键无效';END IF;
 SELECT * INTO a FROM public.ty_pay_adoption WHERE id=substring(NEW.source_key FROM 8)::bigint;
 SELECT * INTO o FROM public.ty_pay_obligation WHERE id=a.obligation_id;SELECT * INTO c FROM public.ty_dorm_charge WHERE id=NEW.charge_id;
 IF a.id IS NULL OR a.source_domain<>'people_candidate'OR(a.source_snapshot->>'charge_id')::bigint IS DISTINCT FROM c.id OR c.group_id IS DISTINCT FROM o.group_id OR c.person_id IS DISTINCT FROM o.person_id OR c.employment_id IS DISTINCT FROM o.employment_id OR NEW.amount<>abs(a.delta)OR(a.delta>0 AND NEW.method<>'payroll')OR(a.delta<0 AND NEW.method<>'refund')OR a.delta=0 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='工资扣结来源须绑定同一真实费用与原生采用，禁止撞号借账';END IF;
 IF NEW.state='confirmed'AND a.state<>'confirmed'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='未确认真实工资不得借旧支付接口假确认扣结';END IF;
 RETURN NEW;END;$$;
CREATE TRIGGER ty_pay_fee_namespace BEFORE INSERT OR UPDATE ON ty_dorm_settlement FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_fee_namespace();
CREATE FUNCTION fn_ty_pay_commit_conservation()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE bid bigint;b public.ty_pay_batch%ROWTYPE;BEGIN
 bid:=CASE WHEN TG_TABLE_NAME='ty_pay_batch'THEN(to_jsonb(NEW)->>'id')::bigint ELSE(to_jsonb(NEW)->>'batch_id')::bigint END;SELECT * INTO b FROM public.ty_pay_batch WHERE id=bid;
 IF EXISTS(SELECT 1 FROM public.ty_pay_adoption a WHERE a.batch_id=bid AND((a.state='confirmed')<>(b.status='confirmed')OR b.status='cancelled'AND a.state<>'released'))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='工资与采用状态必须在同一事务完整确认或释放，不能留半笔账';END IF;RETURN NULL;END;$$;
CREATE CONSTRAINT TRIGGER ty_pay_adoption_commit AFTER INSERT OR UPDATE ON ty_pay_adoption DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_commit_conservation();
CREATE CONSTRAINT TRIGGER ty_pay_batch_commit AFTER UPDATE ON ty_pay_batch DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_commit_conservation();
CREATE TABLE ty_pay_cost_root(
 group_id bigint NOT NULL REFERENCES ty_group(id),economic_component text NOT NULL,recognition_basis text NOT NULL,currency text NOT NULL,
 obligation_id bigint NOT NULL REFERENCES ty_pay_obligation(id),PRIMARY KEY(group_id,economic_component,recognition_basis)
);
CREATE TRIGGER ty_pay_cost_root_immutable BEFORE UPDATE OR DELETE ON ty_pay_cost_root FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_immutable();
CREATE FUNCTION fn_ty_pay_cost_insert()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE a public.ty_pay_adoption%ROWTYPE;o public.ty_pay_obligation%ROWTYPE;i public.ty_pay_item%ROWTYPE;k public.ty_pay_cost_root%ROWTYPE;BEGIN
 SELECT * INTO a FROM public.ty_pay_adoption WHERE id=NEW.adoption_id;SELECT * INTO o FROM public.ty_pay_obligation WHERE id=a.obligation_id;SELECT * INTO i FROM public.ty_pay_item WHERE adoption_id=a.id;
 IF i.id IS NULL OR i.cost_membership<>'independent'OR i.cost_atom IS DISTINCT FROM NEW.economic_component OR NEW.amount<>a.delta*i.cost_direction OR NEW.batch_id<>a.batch_id OR NEW.group_id<>o.group_id OR NEW.company_id<>o.company_id OR NEW.currency<>o.currency THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='成本须来自同一真实工资/费用原子，已含明细和资金不得再增成本';END IF;
 INSERT INTO public.ty_pay_cost_root(group_id,economic_component,recognition_basis,currency,obligation_id)VALUES(NEW.group_id,NEW.economic_component,NEW.recognition_basis,NEW.currency,a.obligation_id)ON CONFLICT DO NOTHING;
 SELECT * INTO k FROM public.ty_pay_cost_root WHERE group_id=NEW.group_id AND economic_component=NEW.economic_component AND recognition_basis=NEW.recognition_basis FOR UPDATE;
 IF k.obligation_id<>a.obligation_id OR k.currency<>NEW.currency THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='同一经济成本原子已由其他来源占用或认列，不得跨币种重复';END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_pay_cost_insert BEFORE INSERT ON ty_pay_cost_entry FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_cost_insert();
CREATE FUNCTION fn_ty_pay_wage_day_insert()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE b public.ty_pay_batch%ROWTYPE;r public.ty_pay_row%ROWTYPE;c public.ty_pay_config%ROWTYPE;v jsonb;BEGIN
 SELECT * INTO b FROM public.ty_pay_batch WHERE id=NEW.batch_id;SELECT * INTO r FROM public.ty_pay_row WHERE id=NEW.row_id;SELECT * INTO c FROM public.ty_pay_config WHERE id=NEW.mapping_config_id;
 IF b.status='confirmed'OR r.batch_id<>b.id OR r.employment_id<>NEW.employment_id OR c.kind<>'wage_calendar'OR c.status<>'approved'OR c.employment_id<>r.employment_id OR c.person_id<>r.person_id OR c.system<>b.system OR NEW.work_date<b.period OR NEW.work_date>=b.period+interval '1 month'OR NEW.root_key<>'wage:'||r.employment_id||':'||to_char(b.period,'YYYY-MM-DD')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='原生工资日必须来自同一未封存工资与已核逐日映射';END IF;
 SELECT x INTO v FROM jsonb_array_elements(c.data->'days')x WHERE x->>'date'=to_char(NEW.work_date,'YYYY-MM-DD');
 IF v IS NULL OR NEW.eligible_wages<>(v->>'eligible_wages')::numeric OR NEW.excluded_wages<>(v->>'excluded_wages')::numeric OR NEW.excluded_days<>(v->>'excluded_days')::numeric OR NEW.ordinary_wages<>(v->>'ordinary_wages')::numeric THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='原生ADW事实金额/排除日数不符合已批准来源';END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_pay_wage_day_insert BEFORE INSERT ON ty_pay_wage_day FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_wage_day_insert();
CREATE FUNCTION fn_ty_pay_wage_day_confirm()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE r public.ty_pay_row%ROWTYPE;e public.ty_employment%ROWTYPE;target numeric;actual numeric;n integer;expected integer;BEGIN
 IF NEW.status<>'confirmed'OR OLD.status='confirmed'OR NEW.system<>'HK_PAYROLL'THEN RETURN NEW;END IF;
 FOR r IN SELECT * FROM public.ty_pay_row WHERE batch_id=NEW.id AND employment_id IS NOT NULL LOOP
  SELECT sum(a.target*CASE WHEN i.cash_wage_effect='decrease_gross'THEN -1 ELSE 1 END)INTO target FROM public.ty_pay_item i JOIN public.ty_pay_adoption a ON a.id=i.adoption_id WHERE i.row_id=r.id AND (i.category='cash_earnings'OR i.cash_wage_effect='decrease_gross')AND i.wage_tags->>'hk_adw'='include';
  IF target IS NULL THEN CONTINUE;END IF;SELECT * INTO e FROM public.ty_employment WHERE id=r.employment_id;
  expected:=least(coalesce(e.leave_date+1,(NEW.period+interval '1 month')::date),(NEW.period+interval '1 month')::date)-greatest(e.hire_date,NEW.period);
  SELECT sum(eligible_wages),count(*)INTO actual,n FROM public.ty_pay_wage_day WHERE row_id=r.id;
  IF actual IS DISTINCT FROM target OR n<>expected THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='原生工资窗须逐日完整且与已确认工资项目目标守恒，缺日不补零';END IF;
 END LOOP;RETURN NEW;END;$$;
CREATE TRIGGER ty_pay_wage_day_confirm BEFORE UPDATE ON ty_pay_batch FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_wage_day_confirm();
-- Reverse provenance is checked against authoritative scope, not only an amount
-- that happens to equal the displayed result.
CREATE FUNCTION fn_ty_pay_reverse_provenance()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE x record;s record;k text;item_code text;rc public.ty_pay_config%ROWTYPE;
BEGIN
 IF NEW.status<>'confirmed'OR OLD.status='confirmed'THEN RETURN NEW;END IF;
 FOR x IN SELECT a.*,i.code,i.cash_wage_effect,i.cost_atom,r.person_id,r.employment_id,r.relationship_config_id,o.economic_key FROM public.ty_pay_adoption a JOIN public.ty_pay_item i ON i.adoption_id=a.id JOIN public.ty_pay_row r ON r.id=i.row_id JOIN public.ty_pay_obligation o ON o.id=a.obligation_id WHERE a.batch_id=NEW.id LOOP
  SELECT * INTO rc FROM public.ty_pay_config WHERE id=x.relationship_config_id;
  IF x.employment_id IS NOT NULL AND(rc.id IS NULL OR rc.kind<>'relationship'OR rc.status<>'approved'OR rc.person_id<>x.person_id OR rc.employment_id<>x.employment_id OR rc.group_id<>NEW.group_id OR rc.company_id<>NEW.company_id OR rc.system<>NEW.system OR rc.data->>'pay_subject_key'IS DISTINCT FROM NEW.pay_subject_key OR rc.data->>'tax_subject_key'IS DISTINCT FROM NEW.tax_subject_key OR rc.data->>'contribution_subject_key'IS DISTINCT FROM NEW.contribution_subject_key)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='工资实际关系与发薪/税务/供款主体必须反向一致';END IF;
  IF x.source_domain='payroll_calculation'THEN
   SELECT * INTO s FROM public.ty_pay_config WHERE id=(x.source_snapshot->>'profile_id')::bigint;
   IF s.group_id<>NEW.group_id OR s.company_id<>NEW.company_id OR s.person_id<>x.person_id OR s.employment_id<>x.employment_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='工资档案来源不能借用其他主体或人员';END IF;
   SELECT 'payroll:'||(rc.data->>'actual_relationship_key')||':'||to_char(NEW.period,'YYYY-MM-DD')||':'||coalesce(metadata->>'exclusion_group',code)INTO k FROM public.ty_pay_item_catalog WHERE code=x.code;
  ELSIF x.source_domain='leave_cash'THEN
   SELECT o.*,r.id rel_id,r.group_id,r.person_id INTO s FROM public.ty_leave_lifecycle_cash_obligation o JOIN public.ty_leave_account a ON a.id=o.account_id JOIN public.ty_leave_relationship r ON r.id=a.relationship_id WHERE o.id=x.source_id::bigint;
   IF s.group_id<>NEW.group_id OR s.person_id<>x.person_id OR NOT EXISTS(SELECT 1 FROM public.ty_leave_relationship_employment WHERE relationship_id=s.rel_id AND employment_id=x.employment_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='假期现金来源须属于同集团同人真实关系';END IF;k:='leave:'||s.rel_id||':'||s.root_key;
  ELSIF x.source_domain='people_candidate'THEN
   SELECT * INTO s FROM public.ty_ps_candidate WHERE id=x.source_id::bigint;
   IF s.group_id<>NEW.group_id OR s.company_id<>NEW.company_id OR s.person_id IS DISTINCT FROM x.person_id OR s.employment_id IS DISTINCT FROM x.employment_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='配套来源不可搬人搬主体';END IF;
   k:='people:'||s.module||':'||s.parent_key||':'||s.kind;
   IF s.kind='employee_charge'THEN
    IF s.source_ref IS DISTINCT FROM 'dorm_charge:'||(x.source_snapshot->>'charge_id')OR NOT EXISTS(SELECT 1 FROM public.ty_dorm_charge c WHERE c.id=(x.source_snapshot->>'charge_id')::bigint AND c.person_id=x.person_id AND c.employment_id=x.employment_id AND c.group_id=NEW.group_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='费用采用须反查同一真实个人费用';END IF;
   ELSIF s.kind='noncash_benefit'THEN k:='people:noncash:'||s.employment_id||':'||to_char(NEW.period,'YYYY-MM-DD')||':'||x.code;
   ELSIF s.kind='company_cost'AND s.cost_basis='allocation'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已含成本分摊只能保留引用，不得伪造新增应付或成本';END IF;
  ELSIF x.source_domain='performance_result'THEN
   SELECT r.*,c.group_id,c.start_date,c.end_date INTO s FROM public.ty_perf_result r JOIN public.ty_perf_cycle c ON c.id=r.cycle_id WHERE r.id=x.source_id::bigint;
   IF s.group_id<>NEW.group_id OR s.person_id<>x.person_id OR s.employment_id<>x.employment_id OR s.company_id<>NEW.company_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='绩效采用必须反查同一永久人员及真实雇佣';END IF;
   k:='performance:'||(rc.data->>'actual_relationship_key')||':'||to_char(s.start_date,'YYYY-MM-DD')||':'||to_char(s.end_date,'YYYY-MM-DD')||':'||to_char(s.period,'YYYY-MM-DD');
  ELSIF x.source_domain='statutory_calculation'THEN k:=public.fn_ty_pay_extension_key(NEW.id,x.id);
  ELSE RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='来源反向适配尚未实现';END IF;
  IF k IS NULL OR x.economic_key IS DISTINCT FROM k THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='工资经济根必须由权威来源反查，不能用规则或路径别名新造义务';END IF;
 END LOOP;RETURN NEW;END;$$;
CREATE TRIGGER ty_pay_reverse_provenance BEFORE UPDATE ON ty_pay_batch FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_reverse_provenance();
